import { promises as fs } from "node:fs";
import * as path from "node:path";

export interface DatabaseConfig {
  readonly dbHost: string;
  readonly dbPort: number;
  readonly [key: string]: unknown;
}

export interface ReadConfigOptions {
  readonly maxSizeBytes?: number;
}

const DEFAULT_MAX_SIZE_BYTES = 1024 * 1024; // 1 MiB limit to prevent unbounded memory allocation

export async function loadDatabaseConfig(
  baseDir: string,
  userSuppliedPath: string,
  options: ReadConfigOptions = {}
): Promise<DatabaseConfig> {
  if (typeof baseDir !== "string" || baseDir.trim().length === 0) {
    throw new TypeError("Base directory path must be a non-empty string.");
  }

  if (typeof userSuppliedPath !== "string" || userSuppliedPath.trim().length === 0) {
    throw new TypeError("User-supplied relative path must be a non-empty string.");
  }

  const maxSizeBytes = options.maxSizeBytes ?? DEFAULT_MAX_SIZE_BYTES;
  if (!Number.isFinite(maxSizeBytes) || maxSizeBytes <= 0) {
    throw new RangeError("maxSizeBytes must be a positive finite number.");
  }

  let canonicalBase: string;
  try {
    canonicalBase = await fs.realpath(path.resolve(baseDir));
  } catch (cause) {
    throw new Error(`Failed to resolve canonical base directory "${baseDir}": ${cause instanceof Error ? cause.message : String(cause)}`, { cause });
  }

  const candidatePath = path.resolve(canonicalBase, userSuppliedPath);

  let canonicalTarget: string;
  try {
    canonicalTarget = await fs.realpath(candidatePath);
  } catch (cause) {
    throw new Error(`Config file not found or inaccessible at "${candidatePath}": ${cause instanceof Error ? cause.message : String(cause)}`, { cause });
  }

  const basePrefix = canonicalBase.endsWith(path.sep) ? canonicalBase : canonicalBase + path.sep;
  if (canonicalTarget !== canonicalBase && !canonicalTarget.startsWith(basePrefix)) {
    throw new Error(`Access denied: resolved path "${canonicalTarget}" escapes allowed base directory "${canonicalBase}".`);
  }

  const stats = await fs.stat(canonicalTarget);
  if (!stats.isFile()) {
    throw new Error(`Resolved path "${canonicalTarget}" is not a regular file.`);
  }

  if (stats.size > maxSizeBytes) {
    throw new RangeError(`Config file size (${stats.size} bytes) exceeds limit of ${maxSizeBytes} bytes.`);
  }

  const fileContents = await fs.readFile(canonicalTarget, "utf8");

  let parsed: unknown;
  try {
    parsed = JSON.parse(fileContents);
  } catch (cause) {
    throw new SyntaxError(`Failed to parse JSON config at "${canonicalTarget}": ${cause instanceof Error ? cause.message : String(cause)}`, { cause });
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new TypeError(`Config root in "${canonicalTarget}" must be a JSON object.`);
  }

  const configRecord = parsed as Record<string, unknown>;

  if (typeof configRecord.dbHost !== "string" || configRecord.dbHost.trim().length === 0) {
    throw new TypeError(`Invalid or missing required field "dbHost" in "${canonicalTarget}": expected non-empty string.`);
  }

  const port = configRecord.dbPort;
  if (typeof port !== "number" || !Number.isInteger(port) || port < 1 || port > 65535) {
    throw new RangeError(`Invalid or missing required field "dbPort" in "${canonicalTarget}": expected integer between 1 and 65535, received ${String(port)}.`);
  }

  return {
    ...configRecord,
    dbHost: configRecord.dbHost.trim(),
    dbPort: port
  };
}
