import { promises as fs } from 'node:fs';
import path from 'node:path';

export interface DatabaseConfig {
  dbHost: string;
  dbPort: number;
  [key: string]: unknown;
}

const MAX_CONFIG_SIZE_BYTES = 10 * 1024 * 1024; // 10 MiB limit against payload exhaustion

/**
 * Loads, canonicalizes, parses, and validates a JSON configuration file.
 *
 * Prevents directory traversal and symlink escape attacks relative to `allowedBaseDir`.
 *
 * @param allowedBaseDir - Absolute or relative path to the permitted root directory.
 * @param userPath - User-supplied relative path to the target JSON configuration.
 * @returns Parsed and validated configuration object.
 */
export async function loadJsonConfig<T extends DatabaseConfig = DatabaseConfig>(
  allowedBaseDir: string,
  userPath: string
): Promise<T> {
  if (typeof allowedBaseDir !== 'string' || allowedBaseDir.trim().length === 0) {
    throw new TypeError('Argument "allowedBaseDir" must be a non-empty string.');
  }
  if (typeof userPath !== 'string' || userPath.trim().length === 0) {
    throw new TypeError('Argument "userPath" must be a non-empty string.');
  }

  // Resolve and canonicalize the base directory to eliminate symlinks and relative segments
  const canonicalBase = await fs.realpath(path.resolve(allowedBaseDir));
  const candidatePath = path.resolve(canonicalBase, userPath);

  // Lexical boundary check
  const lexicalRelative = path.relative(canonicalBase, candidatePath);
  if (lexicalRelative.startsWith('..') || path.isAbsolute(lexicalRelative)) {
    throw new Error(`Access denied: path traverses outside base directory: "${userPath}"`);
  }

  // Canonicalize final target to guard against symlink traversal attacks
  const canonicalTarget = await fs.realpath(candidatePath);
  const targetRelative = path.relative(canonicalBase, canonicalTarget);
  if (targetRelative.startsWith('..') || path.isAbsolute(targetRelative)) {
    throw new Error(`Access denied: symlink points outside base directory: "${canonicalTarget}"`);
  }

  const stat = await fs.stat(canonicalTarget);
  if (!stat.isFile()) {
    throw new Error(`Configuration target is not a regular file: "${canonicalTarget}"`);
  }

  if (stat.size > MAX_CONFIG_SIZE_BYTES) {
    throw new RangeError(
      `Configuration file size (${stat.size} bytes) exceeds limit of ${MAX_CONFIG_SIZE_BYTES} bytes.`
    );
  }

  const rawContent = await fs.readFile(canonicalTarget, { encoding: 'utf-8' });
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawContent);
  } catch (err) {
    throw new Error(`Failed to parse JSON config at "${canonicalTarget}": ${(err as Error).message}`, {
      cause: err,
    });
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new TypeError(`Root JSON element in "${canonicalTarget}" must be an object.`);
  }

  const record = parsed as Record<string, unknown>;

  if (!('dbHost' in record)) {
    throw new TypeError(`Missing required property "dbHost" in "${canonicalTarget}".`);
  }
  if (typeof record.dbHost !== 'string' || record.dbHost.trim().length === 0) {
    throw new TypeError(
      `Invalid "dbHost" in "${canonicalTarget}": expected a non-empty string, received ${typeof record.dbHost}.`
    );
  }

  if (!('dbPort' in record)) {
    throw new TypeError(`Missing required property "dbPort" in "${canonicalTarget}".`);
  }
  if (
    typeof record.dbPort !== 'number' ||
    !Number.isInteger(record.dbPort) ||
    record.dbPort < 1 ||
    record.dbPort > 65535
  ) {
    throw new RangeError(
      `Invalid "dbPort" in "${canonicalTarget}": expected integer between 1 and 65535, received ${JSON.stringify(record.dbPort)}.`
    );
  }

  return record as T;
}
